function planningEquipmentCompatible(array $op,array $resource):bool{if($resource['type']!==$op['type'])return false;$requirement=$op['equipment']??'';$actual=$resource['name'].' '.implode(' ',$resource['capabilities']??[]);foreach(['петельн','пугович','распош','закрепоч','двухиг','плоскош','рукавн','колонк','зигзаг'] as $stem)if(preg_match('~'.$stem.'~iu',$requirement)&&!preg_match('~'.$stem.'~iu',$actual))return false;return true;}
function plannerFit(array $c,array $op,int $after,int $seconds,array &$busy,array $allocation=[],?string $forcePerson=null):?array{
